module Middleware
  # Hardening headers on every response (including the ones generated by the
  # middlewares below us, which never reach the controllers): strips the
  # framework fingerprint, pins the API CSP and adds HSTS on HTTPS when
  # ENABLE_HSTS is on. The Swagger UI under /api/v1/docs gets a relaxed CSP so
  # the vendored bundle and its inline bootstrap keep working.
  class SecurityHeaders
    FINGERPRINT = %w[server x-powered-by x-runtime].freeze
    API_HEADERS = {
      "x-content-type-options" => "nosniff",
      "x-frame-options" => "DENY",
      "referrer-policy" => "no-referrer",
      "cross-origin-opener-policy" => "same-origin",
      "permissions-policy" => "camera=(), microphone=(), geolocation=()",
      "content-security-policy" => "default-src 'none'"
    }.freeze
    DOCS_CSP = [
      "default-src 'self'",
      "script-src 'self' 'unsafe-inline'",
      "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
      "font-src https://fonts.gstatic.com",
      "img-src 'self' data:",
      "connect-src 'self'"
    ].join("; ").freeze
    DOCS_PATH = %r{\A/api/v1/docs}.freeze
    TRUTHY = %w[true 1 yes on].freeze

    def initialize(app)
      @app = app
    end

    def call(env)
      status, headers, body = @app.call(env)

      FINGERPRINT.each { |name| delete_header(headers, name) }
      API_HEADERS.each { |name, value| headers[name] = value }
      headers["content-security-policy"] = DOCS_CSP if env["PATH_INFO"].to_s.match?(DOCS_PATH)
      ensure_vary_origin(headers)
      headers["strict-transport-security"] = "max-age=31536000; includeSubDomains" if https?(env)

      [status, headers, body]
    end

    private

    def https?(env)
      return true if env["rack.url_scheme"] == "https" || env["HTTPS"] == "on"

      # Forwarded proto is only honoured when TRUST_PROXY is on; otherwise
      # TrustProxyHeaders has already dropped the header.
      env["HTTP_X_FORWARDED_PROTO"].to_s.split(",").first.to_s.strip == "https" &&
        TrustProxyHeaders.enabled?
    end

    def delete_header(headers, name)
      headers.keys.each { |key| headers.delete(key) if key.to_s.casecmp?(name) }
    end

    def ensure_vary_origin(headers)
      current = nil
      headers.each { |key, value| current = value if key.to_s.casecmp?("vary") }
      tokens = current.to_s.split(",").map(&:strip).reject(&:empty?)
      return if tokens.any? { |token| token.casecmp?("origin") }

      headers["vary"] = (tokens + ["Origin"]).join(", ")
    end
  end
end
